"""Tests of the header writer (story #37, PRD-TRACE-005, PRD-CORE-038).

Story #167 added the file types of JavaScript and HTML. Story #182 added the
file type of SQL and the extension `.mjs`.
"""

import pytest

from dsml.generate.header import FileType, file_type_of, header, major_version

ELEMENTS = ["R-001", "OrderService::Order", "OrderService::CancelOrder", "R-001"]


@pytest.mark.parametrize(
    ("file_type", "expected"),
    [
        (
            FileType.PYTHON,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.TYPESCRIPT,
            "// Generated by dsml 1. Do not edit.\n"
            "// Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.HCL,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.YAML,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.TOML,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.DOCKERFILE,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.IGNORE,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.INI,
            "# Generated by dsml 1. Do not edit.\n"
            "# Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.JAVASCRIPT,
            "// Generated by dsml 1. Do not edit.\n"
            "// Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (
            FileType.SQL,
            "-- Generated by dsml 1. Do not edit.\n"
            "-- Elements: OrderService::CancelOrder, OrderService::Order, R-001\n",
        ),
        (FileType.JSON, ""),
        (FileType.HTML, ""),
    ],
)
def test_header_form_of_each_file_type(file_type: FileType, expected: str) -> None:
    assert header(file_type, ELEMENTS, version="1.4.2") == expected


def test_each_file_type_has_a_header_test() -> None:
    assert {file_type.value for file_type in FileType} == {
        "dockerfile",
        "hcl",
        "html",
        "ignore",
        "ini",
        "javascript",
        "json",
        "python",
        "sql",
        "toml",
        "typescript",
        "yaml",
    }


@pytest.mark.parametrize("version", ["1.0.0", "1.4.2", "1.99.0rc1", "1"])
def test_header_gives_only_the_major_version(version: str) -> None:
    text = header(FileType.PYTHON, ["R-001"], version=version)
    assert text.splitlines()[0] == "# Generated by dsml 1. Do not edit."


def test_header_of_the_installed_toolchain() -> None:
    assert major_version() == "0"
    assert header(FileType.PYTHON, ["R-001"]).startswith("# Generated by dsml 0. Do not edit.\n")


def test_header_with_no_elements() -> None:
    assert header(FileType.YAML, [], version="1.0.0") == (
        "# Generated by dsml 1. Do not edit.\n# Elements:\n"
    )


def test_header_sorts_by_code_point() -> None:
    text = header(FileType.PYTHON, ["b", "B", "a", "A"], version="1.0.0")
    assert text.splitlines()[1] == "# Elements: A, B, a, b"


@pytest.mark.parametrize("identity", ["", " R-001", "R-001\n# x", "R-001\r"])
def test_header_rejects_an_identity_that_is_not_correct(identity: str) -> None:
    with pytest.raises(ValueError, match="is not correct for a header"):
        header(FileType.PYTHON, [identity], version="1.0.0")


@pytest.mark.parametrize("version", ["", "v1.0.0", "x"])
def test_major_version_errors(version: str) -> None:
    with pytest.raises(ValueError, match="does not start with a major version"):
        major_version(version)


@pytest.mark.parametrize(
    ("path", "file_type"),
    [
        ("app/main_gen.py", FileType.PYTHON),
        ("src/api.gen.ts", FileType.TYPESCRIPT),
        ("src/page.gen.tsx", FileType.TYPESCRIPT),
        ("infra/network.gen.tf", FileType.HCL),
        ("infra/terragrunt.hcl", FileType.HCL),
        (".github/workflows/ci.gen.yml", FileType.YAML),
        ("config.gen.yaml", FileType.YAML),
        ("pyproject.toml", FileType.TOML),
        ("eslint.config.js", FileType.JAVASCRIPT),
        ("migrate.gen.mjs", FileType.JAVASCRIPT),
        ("migrations/0001_create_order.gen.sql", FileType.SQL),
        ("index.html", FileType.HTML),
        ("services/api/alembic.ini", FileType.INI),
        ("Dockerfile", FileType.DOCKERFILE),
        ("docker/api.Dockerfile", FileType.DOCKERFILE),
        (".dsml/trace.gen.json", FileType.JSON),
    ],
)
def test_file_type_of(path: str, file_type: FileType) -> None:
    assert file_type_of(path) == file_type


def test_file_type_of_an_unknown_file() -> None:
    with pytest.raises(ValueError, match="does not have a known file type"):
        file_type_of("README.md")
